def should_retry(status, method='GET'):
    if status == 429:
        return True
    return status == 503 and method.upper() in {'GET', 'HEAD'}

def delay_seconds(attempt):
    if attempt < 1:
        raise ValueError('attempt')
    return min(2 ** (attempt - 1), 16)

